def parse_custom_run_seconds(value: Any) -> int:
    """Parse an editable timing value without Tk's float-to-int truncation."""
    if isinstance(value, bool):
        raise ValueError("Enter a whole number from 30 to 1,800 seconds")
    if isinstance(value, int):
        seconds = value
    elif isinstance(value, str) and len(value.strip()) <= 16 and re.fullmatch(r"[0-9]+", value.strip()):
        seconds = int(value.strip())
    else:
        raise ValueError("Enter a whole number from 30 to 1,800 seconds")
    if not 30 <= seconds <= 1_800:
        raise ValueError("Run time must be between 30 and 1,800 seconds")
    return seconds

