def _run_profile_presets_editable(self, state: dict[str, Any] | None = None) -> bool:
    """Recheck configuration authority when a delayed dialog/menu fires."""
    current = state if state is not None else read_state(self.control_path)
    worker = current.get("worker") or {}
    _stats, checkpoint = self._stats()
    if not isinstance(checkpoint, dict):
        return False
    resumable = checkpoint_is_resumable(
        runtime_mission(self.mission_path, controller_state=current), checkpoint,
    )
    terminal = controller_terminal_disposition(current, checkpoint)
    available = action_availability(
        str(current.get("desired_state") or "blocked"),
        worker_active=self._worker_active(),
        persisted_worker_status=str(worker.get("status") or "idle"),
        checkpoint_resumable=resumable,
        terminal_disposition=terminal,
    )
    return available.start and self._heart_conflict_for_universal() is None

def _selected_run_profile_preset(self) -> dict[str, Any] | None:
    selected = getattr(self, "selected_run_profile_preset_id", None)
    return next((
        item for item in getattr(self, "run_profile_presets", [])
        if item["id"] == selected
    ), None)

def _refresh_run_profile_preset_menu(self, state: dict[str, Any] | None = None) -> None:
    if state is not None:
        self.run_profile_presets = normalize_run_profile_presets(
            state.get("run_profile_presets")
        )
        self.selected_run_profile_preset_id = state.get("selected_run_profile_preset_id")
    choice = getattr(self, "run_profile_preset_choice", None)
    if choice is None:
        return
    if state is not None:
        self._run_profile_preset_authority_enabled = self._run_profile_presets_editable(state)
    selected = self._selected_run_profile_preset()
    try:
        profile = self._run_profile()
    except ValueError:
        profile = None
    # A saved preference must never label a different frozen active Plan.
    matches = (
        selected is not None and profile is not None
        and profile["mode"] == "custom"
        and profile["expected_seconds"] == selected["expected_seconds"]
    )
    choice.set(
        f"{selected['name']} · {selected['expected_seconds']}s" if matches
        else "Choose a saved time" if self.run_profile_presets
        else "No saved times — use SAVE AS"
    )
    menu_widget = getattr(self, "run_profile_preset_menu", None)
    if menu_widget is not None:
        signature = tuple((x["id"], x["name"], x["expected_seconds"]) for x in self.run_profile_presets)
        if signature != getattr(self, "_run_profile_preset_menu_signature", None):
            menu = menu_widget["menu"]
            menu.delete(0, END)
            for item in self.run_profile_presets:
                menu.add_command(
                    label=f"{item['name']} · {item['expected_seconds']}s",
                    command=lambda preset_id=item["id"]: self._choose_run_profile_preset(preset_id),
                )
            self._run_profile_preset_menu_signature = signature
    self._sync_run_profile_preset_controls()

def _sync_run_profile_preset_controls(self) -> None:
    enabled = (
        getattr(self, "configuration_enabled", True)
        and getattr(self, "_run_profile_preset_authority_enabled", True)
    )
    selected = self._selected_run_profile_preset() is not None
    menu = getattr(self, "run_profile_preset_menu", None)
    if menu is not None:
        menu.configure(state="normal" if enabled and self.run_profile_presets else "disabled")
    for name, available in (
        ("run_profile_preset_save_button", enabled),
        ("run_profile_preset_edit_button", enabled and selected),
        ("run_profile_preset_delete_button", enabled and selected),
    ):
        button = getattr(self, name, None)
        if button is not None:
            button.set_enabled(available)

def _apply_run_profile_preset(self, item: dict[str, Any]) -> None:
    self._applying_run_profile_preset = True
    try:
        self.run_profile_mode.set("custom")
        self.custom_run_seconds.set(str(item["expected_seconds"]))
    finally:
        self._applying_run_profile_preset = False
    self._sync_run_profile_controls()
    self._refresh_run_profile_preset_menu()

def _restore_run_profile_preset_selection(self, state: dict[str, Any]) -> None:
    """Restore an idle draft only; Resume always keeps its frozen Plan."""
    self._refresh_run_profile_preset_menu(state)
    item = self._selected_run_profile_preset()
    if item is None or not self._run_profile_presets_editable(state):
        return
    _stats, checkpoint = self._stats()
    if checkpoint_is_resumable(
        runtime_mission(self.mission_path, controller_state=state), checkpoint,
    ):
        return
    self._apply_run_profile_preset(item)

def _choose_run_profile_preset(self, preset_id: str) -> ControllerCommandResult:
    try:
        if not self._run_profile_presets_editable():
            return ControllerCommandResult(False, "configuration_locked", "Stop or finish the current job before changing run times.")
        state = select_run_profile_preset(self.control_path, preset_id)
        self._refresh_run_profile_preset_menu(state)
        item = self._selected_run_profile_preset()
        if item is None:
            raise ValueError("This saved time no longer exists. Select another preset.")
        self._apply_run_profile_preset(item)
        return ControllerCommandResult(True, "preset_selected", f"{item['name']} · {item['expected_seconds']} seconds")
    except (OSError, RuntimeError, TypeError, ValueError) as exc:
        messagebox.showerror("Run time preset", str(exc))
        return ControllerCommandResult(False, "preset_unavailable", str(exc))

def _save_run_profile_preset_values(
    self, *, name: str, seconds: Any, preset_id: str | None = None,
) -> ControllerCommandResult:
    try:
        if not self._run_profile_presets_editable():
            return ControllerCommandResult(False, "configuration_locked", "Stop or finish the current job before saving run times.")
        state = save_run_profile_preset(
            self.control_path, name=name,
            expected_seconds=parse_custom_run_seconds(seconds), preset_id=preset_id,
        )
        self._refresh_run_profile_preset_menu(state)
        item = self._selected_run_profile_preset()
        if item is None:
            raise ValueError("The saved preset is unavailable. Reopen the preset list.")
        self._apply_run_profile_preset(item)
        return ControllerCommandResult(True, "preset_saved", f"Saved {item['name']} · {item['expected_seconds']} seconds")
    except (OSError, RuntimeError, TypeError, ValueError) as exc:
        return ControllerCommandResult(False, "invalid_preset", str(exc))

def _clear_run_profile_preset_selection(self) -> None:
    if not getattr(self, "selected_run_profile_preset_id", None):
        return
    try:
        if self._run_profile_presets_editable():
            state = select_run_profile_preset(self.control_path, None)
            self._refresh_run_profile_preset_menu(state)
    except (OSError, RuntimeError, TypeError, ValueError) as exc:
        messagebox.showerror("Run time preference was not saved", str(exc))

def _manual_run_profile_changed(self) -> None:
    self._clear_run_profile_preset_selection()
    self._sync_run_profile_controls()

def _custom_run_seconds_changed(self) -> None:
    if getattr(self, "_applying_run_profile_preset", False):
        return
    self._clear_run_profile_preset_selection()
    self._sync_run_profile_controls()

def _new_run_profile_preset(self) -> None:
    self._open_run_profile_preset_dialog()

def _edit_run_profile_preset(self) -> None:
    item = self._selected_run_profile_preset()
    if item is not None:
        self._open_run_profile_preset_dialog(item)

def _delete_selected_run_profile_preset(self) -> None:
    try:
        if not self._run_profile_presets_editable():
            return
        item = self._selected_run_profile_preset()
        if item is None or not messagebox.askyesno(
            "Delete saved run time", f"Delete “{item['name']}”?\n\nThe current run time will stay unchanged.",
        ):
            return
        # The confirmation can outlive a worker transition.
        if not self._run_profile_presets_editable():
            return
        state = delete_run_profile_preset(self.control_path, item["id"])
        self._refresh_run_profile_preset_menu(state)
    except (OSError, RuntimeError, TypeError, ValueError) as exc:
        messagebox.showerror("Run time preset", str(exc))

