    self._run_profile_preset_dialog = dialog
    dialog.title("Edit run time preset" if item else "Save run time preset")
    dialog.configure(bg=PANEL)
    dialog.resizable(False, False)
    dialog.transient(self.root)
    body = Frame(dialog, bg=PANEL, padx=22, pady=20)
    body.pack(fill=BOTH, expand=True)
    Label(body, text="EDIT RUN TIME" if item else "SAVE RUN TIME", bg=PANEL,
          fg=TEXT, font=("Segoe UI Semibold", 13)).grid(row=0, column=0, columnspan=2, sticky="w")
    Label(body, text="Save a name and duration for each farming setup.", bg=PANEL,
          fg=MUTED, font=("Segoe UI", 9)).grid(row=1, column=0, columnspan=2, sticky="w", pady=(6, 18))
    name_value = StringVar(value=item["name"] if item else "")
    seconds_value = StringVar(value=str(item["expected_seconds"] if item else expected))
