        Label(body, text=label, bg=PANEL, fg=MUTED, font=("Segoe UI", 9)).grid(row=row, column=0, sticky="w", padx=(0, 18), pady=(0, 12))
        entry = Entry(body, textvariable=variable, width=32, bg=PANEL_ALT, fg=TEXT,
                      insertbackground=GOLD, relief="flat", highlightthickness=1,
                      highlightbackground=BORDER, highlightcolor=GOLD, font=("Segoe UI", 10))
        entry.grid(row=row, column=1, sticky="ew", ipady=7, pady=(0, 12))
        entries.append(entry)
    Label(body, text="30–1,800 whole seconds. Relay uses the first runner’s time.",
          bg=PANEL, fg=MUTED, font=("Segoe UI", 8)).grid(row=4, column=0, columnspan=2, sticky="w")
    error = StringVar(value="")
    Label(body, textvariable=error, bg=PANEL, fg=RED, font=("Segoe UI", 9),
