    RoundedButton(actions, "CANCEL", close, width=88, height=34, accent=MUTED).pack(side=LEFT, padx=(0, 8))
    RoundedButton(actions, "SAVE PRESET", save, width=118, height=34, filled=True).pack(side=LEFT)
    dialog.protocol("WM_DELETE_WINDOW", close)
    dialog.bind("<Escape>", lambda _event: close())

    def save_on_return(_event: Any) -> str:
