def _run_profile_preset_name(value: Any) -> str:
    if not isinstance(value, str):
        raise ValueError("Preset name must be text")
    value = unicodedata.normalize("NFC", value)
    if any(unicodedata.category(character).startswith("C") for character in value):
        raise ValueError("Preset name cannot contain control characters")
    name = " ".join(value.split())
    if not name or len(name) > RUN_PROFILE_PRESET_NAME_MAX_LENGTH:
        raise ValueError(
            f"Preset name must contain 1–{RUN_PROFILE_PRESET_NAME_MAX_LENGTH} characters"
        )
    return name


def _run_profile_preset_seconds(value: Any) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or not 30 <= value <= 1_800:
        raise ValueError("Preset time must be a whole number from 30 to 1800 seconds")
    return value


def _run_profile_preset_id(value: Any) -> str:
    if (
        not isinstance(value, str)
        or len(value) != 32
        or any(character not in "0123456789abcdef" for character in value)
    ):
        raise ValueError("Unknown Run Profile preset")
    return value


def normalize_run_profile_presets(value: Any) -> list[dict[str, Any]]:
    """Read only bounded valid preference rows, without changing a live Plan.

    A damaged optional preset does not invalidate an otherwise valid running
    Controller. It is omitted rather than converted into an AUTO profile or a
    replacement duration. Duplicate names/ids retain the first valid row.
    """
    if not isinstance(value, list):
        return []
    presets: list[dict[str, Any]] = []
    seen_ids: set[str] = set()
    seen_names: set[str] = set()
    for row in value:
        if not isinstance(row, dict):
            continue
        try:
            preset_id = _run_profile_preset_id(row.get("id"))
            name = _run_profile_preset_name(row.get("name"))
            seconds = _run_profile_preset_seconds(row.get("expected_seconds"))
        except ValueError:
            continue
        if preset_id in seen_ids or name.casefold() in seen_names:
            continue
        presets.append({"id": preset_id, "name": name, "expected_seconds": seconds})
        seen_ids.add(preset_id)
        seen_names.add(name.casefold())
        if len(presets) == RUN_PROFILE_PRESET_MAX_COUNT:
            break
    return presets


def normalize_selected_run_profile_preset_id(
    value: Any, presets: list[dict[str, Any]]
) -> str | None:
    """A missing/deleted preference never selects another row implicitly."""
    return value if isinstance(value, str) and any(row["id"] == value for row in presets) else None


def save_run_profile_preset(
    path: Path,
    *,
    name: str,
    expected_seconds: int,
    preset_id: str | None = None,
) -> dict[str, Any]:
    """Atomically save and select a named timing, without editing run authority.

    The Controller applies this timing to its editable UI as an ordinary Custom
    Run Profile. The stored library and selected id are preferences only; the
    Bridge never dereferences them while starting/resuming a frozen Batch.
    """
    name = _run_profile_preset_name(name)
    seconds = _run_profile_preset_seconds(expected_seconds)
    if preset_id is not None:
        preset_id = _run_profile_preset_id(preset_id)
    with state_write_lock(path):
        state = _read_state_unlocked(path, require_existing=False)
        presets = normalize_run_profile_presets(state.get("run_profile_presets"))
        matching = next((index for index, row in enumerate(presets) if row["id"] == preset_id), None)
        if preset_id is not None and matching is None:
            raise ValueError("Unknown Run Profile preset")
        if any(row["name"].casefold() == name.casefold() and row["id"] != preset_id for row in presets):
            raise ValueError("A preset with this name already exists")
        if matching is None and len(presets) >= RUN_PROFILE_PRESET_MAX_COUNT:
            raise ValueError(f"You can save up to {RUN_PROFILE_PRESET_MAX_COUNT} presets")
        saved_id = preset_id or uuid.uuid4().hex
        row = {"id": saved_id, "name": name, "expected_seconds": seconds}
        if matching is None:
            presets.append(row)
        else:
            presets[matching] = row
        if presets == state.get("run_profile_presets") and state.get("selected_run_profile_preset_id") == saved_id:
            return state
        state["run_profile_presets"] = presets
        state["selected_run_profile_preset_id"] = saved_id
        return _write_state_unlocked(path, state)


def delete_run_profile_preset(path: Path, preset_id: str) -> dict[str, Any]:
    """Delete one preference; deleting a selection never chooses a fallback."""
    preset_id = _run_profile_preset_id(preset_id)
    with state_write_lock(path):
        state = _read_state_unlocked(path, require_existing=False)
        presets = normalize_run_profile_presets(state.get("run_profile_presets"))
        remaining = [row for row in presets if row["id"] != preset_id]
        if len(remaining) == len(presets):
            raise ValueError("Unknown Run Profile preset")
        state["run_profile_presets"] = remaining
        state["selected_run_profile_preset_id"] = normalize_selected_run_profile_preset_id(
            state.get("selected_run_profile_preset_id"), remaining
        )
        return _write_state_unlocked(path, state)


def select_run_profile_preset(path: Path, preset_id: str | None) -> dict[str, Any]:
    """Persist only the selection preference, keeping the frozen Plan exact."""
    if preset_id is not None:
        preset_id = _run_profile_preset_id(preset_id)
    with state_write_lock(path):
        state = _read_state_unlocked(path, require_existing=False)
        presets = normalize_run_profile_presets(state.get("run_profile_presets"))
        if preset_id is not None and not any(row["id"] == preset_id for row in presets):
            raise ValueError("Unknown Run Profile preset")
        if state.get("selected_run_profile_preset_id") == preset_id:
            return state
        state["selected_run_profile_preset_id"] = preset_id
        return _write_state_unlocked(path, state)

state["run_profile_presets"] = normalize_run_profile_presets(
    previous.get("run_profile_presets")
)
state["selected_run_profile_preset_id"] = normalize_selected_run_profile_preset_id(
    previous.get("selected_run_profile_preset_id"), state["run_profile_presets"]
)
